import React, { useState } from 'react';
import { Stat, PageTitle, Field, Modal, Status, Empty } from '../common';
import './ReportsPage.css';

export default function ReportsPage({leads,employees,properties,money}) { const stages=['New','Qualified','Hot','Site Visit','Negotiation','Won','Lost']; const max=Math.max(...stages.map(s=>leads.filter(l=>l.status===s).length),1); return <div className="module-page module-page--reports"><PageTitle eyebrow="BUSINESS INTELLIGENCE" title="Reports & insights" subtitle="Understand pipeline health and your team's workload at a glance."/><div className="stats-grid"><Stat label="Open pipeline value" value={money(leads.filter(l=>!['Won','Lost'].includes(l.status)).reduce((s,l)=>s+Number(l.budget||0),0))} change="Budget sum, not forecast" icon="₹" tone="purple" foot="Review probability weighting"/><Stat label="Conversion rate" value={`${leads.length?Math.round(leads.filter(l=>l.status==='Won').length/leads.length*100):0}%`} change="Won / total leads" icon="↗" tone="green" foot="Demo data calculation"/><Stat label="Team size" value={employees.length} change="Current roster" icon="♙" tone="blue" foot="No productivity scoring yet"/><Stat label="Inventory value" value={money(properties.reduce((s,p)=>s+Number(p.price||0),0))} change="Sum of listing prices" icon="⌂" tone="orange" foot="Not company-owned asset value"/></div><div className="dashboard-grid"><div className="panel"><div className="panel-head"><div><h3>Pipeline distribution</h3><p>Lead count by stage</p></div></div><div className="pipeline-bars report-bars">{stages.map((s,i)=>{const count=leads.filter(l=>l.status===s).length;return <div className="pipeline-row" key={s}><span>{s}</span><div className="bar-track"><div className="bar-fill" style={{width:`${count/max*100}%`}}/></div><b>{count}</b></div>})}</div></div><div className="panel"><div className="panel-head"><div><h3>Suggested actions</h3><p>Improve the quality of reporting</p></div></div><div className="insight-list"><div><span className="insight-badge purple">01</span><p><b>Capture lost reasons</b><small>Understand why opportunities are not converting.</small></p></div><div><span className="insight-badge orange">02</span><p><b>Track response time</b><small>Use timestamped activities from the backend.</small></p></div><div><span className="insight-badge green">03</span><p><b>Verify property availability</b><small>Keep last-confirmed date and source for every listing.</small></p></div></div></div></div></div>; }
